  "sql": "WITH part AS (SELECT p.portfolio_id, p.portfolio_name, SUM(h.quantity * s.current_price) AS tech_value FROM holdings h JOIN securities s ON s.security_id = h.security_id JOIN sectors sec ON sec.sector_id = s.sector_id JOIN portfolios p ON p.portfolio_id = h.portfolio_id WHERE sec.sector_name = 'Technology' GROUP BY p.portfolio_id, p.portfolio_name), whole AS (SELECT p.portfolio_id, SUM(h.quantity * s.current_price) AS total_value FROM holdings h JOIN securities s ON s.security_id = h.security_id JOIN portfolios p ON p.portfolio_id = h.portfolio_id GROUP BY p.portfolio_id) SELECT part.portfolio_name, part.tech_value, whole.total_value, ROUND(part.tech_value * 100.0 / whole.total_value, 2) AS tech_percentage FROM part JOIN whole ON whole.portfolio_id = part.portfolio_id ORDER BY tech_percentage DESC",
